import { useCallback, useState } from 'react';
import Task from './task';
import Settings from './settings';
import AdminOverview from './admin-overview';
import Notification from './notification';
import './dashboard.css';

function Dashboard({ user, userName, userRole, onLogout }) {
  const [activePage, setActivePage] = useState('Dashboard');
  const [search, setSearch] = useState('');
  const [taskStats, setTaskStats] = useState({ total: 0, completed: 0, remaining: 0 });
  const [workspaceName, setWorkspaceName] = useState('Task Manager');
  const [displayName, setDisplayName] = useState(userName);
  const [unreadNotifications, setUnreadNotifications] = useState(3);

  const updateTaskStats = useCallback((stats) => setTaskStats(stats), []);
  const progress = taskStats.total ? Math.round((taskStats.completed / taskStats.total) * 100) : 0;
  const pages = [['Dashboard'], ['Tasks'], ['Projects'], ['Analytics'], ['Calendar']];
  const firstName = displayName.trim().split(' ')[0];
  const roleMessage = userRole === 'Admin'
    ? 'You have a clear view of the whole workspace today.'
    : userRole === 'Manager'
      ? 'Keep your team aligned and moving forward today.'
      : 'A focused space for the work that matters today.';
  const summaryCards = (
    <section className="metric-grid" aria-label="Task summary">
      <article className="metric-card blue"><span>Total tasks</span><strong>{taskStats.total}</strong><small>Across your workspace</small></article>
      <article className="metric-card green"><span>Completed</span><strong>{taskStats.completed}</strong><small>{progress}% of your workload</small></article>
      <article className="metric-card purple"><span>Remaining</span><strong>{taskStats.remaining}</strong><small>{taskStats.remaining ? 'Keep the momentum going' : 'You are all caught up'}</small></article>
      <article className="metric-card pink"><span>Completion rate</span><strong>{progress}%</strong><small>Today&apos;s progress</small></article>
    </section>
  );

  return (
    <main className="dashboard-page">
      <div className="dashboard-shell">
        <aside className="dashboard-sidebar">
          <div className="product-logo"><span className="logo-icon"></span><span>{workspaceName}<small>WORKSPACE</small></span></div>
          <p className="menu-label">Menu</p>
          <nav aria-label="Main navigation">
            {pages.map(([page]) => (
              <button className={`nav-item ${activePage === page ? 'active' : ''}`} type="button" key={page} onClick={() => setActivePage(page)}><span aria-hidden="true">{page === 'Dashboard' ? '' : page === 'Tasks' ? '' : page === 'Projects' ? '' : page === 'Analytics' ? '' : ''}</span>{page}</button>
            ))}
            {userRole !== 'User' && <button className={`nav-item ${activePage === 'Team Members' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Team Members')}><span aria-hidden="true"></span>Team Members</button>}
            {userRole === 'Admin' && <button className={`nav-item ${activePage === 'Manage Users' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Manage Users')}><span aria-hidden="true"></span>Manage Users</button>}
          </nav>
          <p className="menu-label general-label">General</p>
          <button className={`nav-item ${activePage === 'Settings' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Settings')}><span aria-hidden="true"></span>Settings</button>
          <button className="nav-item" type="button" onClick={onLogout}><span aria-hidden="true"></span>Logout</button>
          <div className="upgrade-box"><span className="upgrade-mark"></span><strong>{userRole} workspace</strong><p>Plan, track, and finish meaningful work.</p></div>
        </aside>

        <section className="dashboard-main">
          <header className="dashboard-topbar">
            <div><p className="dashboard-label">{activePage} </p><h1>Good morning, {firstName} <span aria-hidden="true"></span></h1><p>{roleMessage}</p></div>
            <div className="topbar-actions"><label className="search-box"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search tasks..." aria-label="Search tasks" /></label><button className="notification-button" type="button" onClick={() => setActivePage('Notifications')} aria-label="Open notifications" title="Notifications"><span aria-hidden="true">&#128276;</span>{unreadNotifications > 0 && <b>{unreadNotifications}</b>}</button><div className="account-box"><span className="user-avatar">{displayName.charAt(0).toUpperCase()}</span><span><strong>{displayName}</strong><small>{userRole} account</small></span></div></div>
          </header>

          {activePage === 'Dashboard' && (
            <>
              {summaryCards}
              <div className="dashboard-grid"><Task search={search} compact userRole={userRole} onStats={updateTaskStats} assignedBy={displayName} assignedTo={displayName} assignedUserId={user?.id} /><article className="panel progress-panel"><div className="panel-heading"><div><p className="dashboard-label">Your rhythm</p><h2>Today&apos;s progress</h2><p>{progress === 100 ? 'Everything is complete.' : 'Small steps add up.'}</p></div></div><div className="progress-circle" style={{ '--progress': `${progress}%` }}><strong>{progress}%</strong></div><p>{progress === 100 ? 'All tasks completed!' : `${taskStats.remaining} tasks left to finish.`}</p></article></div>
            </>
          )}

          {activePage === 'Tasks' && <>{summaryCards}<Task search={search} userRole={userRole} onStats={updateTaskStats} assignedBy={displayName} assignedTo={displayName} assignedUserId={user?.id} /></>}
          {activePage === 'Manage Users' && <AdminOverview search={search} />}
          {activePage === 'Notifications' && <Notification userName={displayName} userRole={userRole} taskStats={taskStats} onUnreadChange={setUnreadNotifications} />}
          {activePage === 'Settings' && <Settings user={user} userName={displayName} userRole={userRole} onWorkspaceNameChange={setWorkspaceName} onProfileNameChange={setDisplayName} />}
          {activePage !== 'Dashboard' && activePage !== 'Tasks' && activePage !== 'Settings' && activePage !== 'Manage Users' && activePage !== 'Notifications' && <section className="working-page panel"><p className="dashboard-label">Workspace</p><h2>{activePage}</h2><p>This section is ready for your {activePage.toLowerCase()}.</p></section>}
        </section>
      </div>
    </main>
  );
}

export default Dashboard;
